-- `Variant` and `Dynamic` columns generated by `generateRandom`.
-- `null_ratio` is a setting of the table function, so it has to be passed inside the call.

SELECT '-- Variant: every variant and the untyped NULL appear';
-- `variantType` returns an `Enum`, so it is cast to `String` to sort the names alphabetically.
SELECT arraySort(groupUniqArray(variantType(v)::String))
FROM (SELECT * FROM generateRandom('v Variant(UInt64, String, Array(UInt8))', 1) LIMIT 1000);

SELECT '-- Variant: null_ratio = 0 leaves no NULL';
SELECT countIf(variantType(v) = 'None')
FROM (SELECT * FROM generateRandom('v Variant(UInt64, String, Array(UInt8))', 1, SETTINGS null_ratio = 0) LIMIT 1000);

SELECT '-- Dynamic: between 1 and 4 types, and NULLs at the default ratio';
SELECT uniqExactIf(t, t != 'None') BETWEEN 1 AND 4, countIf(t = 'None') > 0
FROM (SELECT dynamicType(d) AS t FROM generateRandom('d Dynamic', 1) LIMIT 1000);

SELECT '-- Dynamic: every type name is a pool member';
SELECT countIf(NOT match(t, '^(String|Int64|Float64|Bool|DateTime|Date|UInt64|Array\\(Nullable\\((String|Int64|Float64|Bool|DateTime|Date|UInt64)\\)\\))$'))
FROM (SELECT dynamicType(d) AS t FROM generateRandom('d Dynamic', 1, SETTINGS null_ratio = 0) LIMIT 1000);

SELECT '-- Dynamic(max_types=1): seed 1 draws three types, one gets a variant of its own and the two others spill into the shared variant';
-- The set of types does not shrink with `max_types`: the excess types are encoded into the shared
-- variant, the way a `Dynamic` column stores the types it has no variant left for.
SELECT uniqExact(dynamicType(d)), countIf(isDynamicElementInSharedData(d)) > 0, uniqExactIf(dynamicType(d), NOT isDynamicElementInSharedData(d))
FROM (SELECT * FROM generateRandom('d Dynamic(max_types=1)', 1, SETTINGS null_ratio = 0) LIMIT 1000);

-- The shared values survive a `MergeTree` round trip: the table reads back the same types in the same numbers.
DROP TABLE IF EXISTS t_generate_random_dynamic_one;
CREATE TABLE t_generate_random_dynamic_one (d Dynamic(max_types=1)) ENGINE = MergeTree ORDER BY tuple();
INSERT INTO t_generate_random_dynamic_one SELECT * FROM generateRandom('d Dynamic(max_types=1)', 1, SETTINGS null_ratio = 0) LIMIT 300;
SELECT (SELECT arraySort(groupArray((t, c))) FROM (SELECT dynamicType(d) AS t, count() AS c FROM t_generate_random_dynamic_one GROUP BY t))
     = (SELECT arraySort(groupArray((t, c))) FROM (SELECT dynamicType(d) AS t, count() AS c
                                                    FROM (SELECT * FROM generateRandom('d Dynamic(max_types=1)', 1, SETTINGS null_ratio = 0) LIMIT 300) GROUP BY t));
DROP TABLE t_generate_random_dynamic_one;

SELECT '-- Dynamic(max_types=0): every value lives in the shared variant';
SELECT count(), uniqExact(dynamicType(d)), countIf(NOT isDynamicElementInSharedData(d)),
       countIf(match(dynamicType(d), '^(String|Int64|Float64|Bool|DateTime|Date|UInt64|Array\\(Nullable\\((String|Int64|Float64|Bool|DateTime|Date|UInt64)\\)\\))$'))
FROM (SELECT * FROM generateRandom('d Dynamic(max_types=0)', 1, SETTINGS null_ratio = 0) LIMIT 100);

DROP TABLE IF EXISTS t_generate_random_dynamic;
CREATE TABLE t_generate_random_dynamic (d Dynamic(max_types=0)) ENGINE = MergeTree ORDER BY tuple();
INSERT INTO t_generate_random_dynamic SELECT * FROM generateRandom('d Dynamic(max_types=0)', 1, SETTINGS null_ratio = 0) LIMIT 100;
SELECT count(), uniqExact(dynamicType(d)) FROM t_generate_random_dynamic;
DROP TABLE t_generate_random_dynamic;

SELECT '-- the same seed gives the same values twice';
DROP TABLE IF EXISTS t_generate_random_seeded;
CREATE TABLE t_generate_random_seeded (run UInt8, s String) ENGINE = MergeTree ORDER BY (run, s);
INSERT INTO t_generate_random_seeded SELECT 1, toString(d) FROM generateRandom('d Dynamic', 42) LIMIT 500;
INSERT INTO t_generate_random_seeded SELECT 2, toString(d) FROM generateRandom('d Dynamic', 42) LIMIT 500;
SELECT uniqExact(h) FROM (SELECT run, cityHash64(arraySort(groupArray(s))) AS h FROM t_generate_random_seeded GROUP BY run);
DROP TABLE t_generate_random_seeded;

SELECT '-- Array(Dynamic): strings mixed with one number type';
SELECT arraySort(groupUniqArray(t))
FROM (SELECT dynamicType(arrayJoin(a)) AS t FROM generateRandom('a Array(Dynamic)', 1, SETTINGS null_ratio = 0) LIMIT 1000);

SELECT '-- containers of Variant and Dynamic';
SELECT count() FROM (SELECT * FROM generateRandom('m Map(String, Variant(UInt64, String))', 1) LIMIT 100);
SELECT count() FROM (SELECT * FROM generateRandom('t Tuple(Variant(UInt64, String), Dynamic)', 1) LIMIT 100);

DROP TABLE IF EXISTS t_generate_random_nested;
CREATE TABLE t_generate_random_nested (n Nested(a Dynamic, b UInt8), v Variant(UInt64, String)) ENGINE = GenerateRandom(1);
SELECT count() FROM (SELECT * FROM t_generate_random_nested LIMIT 100);
DROP TABLE t_generate_random_nested;

SELECT '-- seeded values';
SELECT * FROM generateRandom('v Variant(UInt64, String, Array(UInt8)), d Dynamic', 1) LIMIT 3;
